[metadata] {"type": "create", "filePath": "/app/output/index.html", "content": "<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>MedBook — Find and Book Top Doctors Instantly</title>
<link rel="preconnect" href="https://fonts.googleapis.com">
<link rel="preconnect" href="https://fonts.gstatic.com" crossorigin>
<link href="https://fonts.googleapis.com/css2?family=Inter:wght@400;500;600;700;800&display=swap" rel="stylesheet">
<style>
/* ===== DESIGN TOKENS (OKLCH) ===== */
:root {
  --blue-primary: oklch(52% 0.22 264);
  --blue-primary-hover: oklch(45% 0.24 264);
  --blue-light: oklch(95% 0.04 264);
  --blue-bg: oklch(97% 0.02 264);
  --teal-accent: oklch(62% 0.16 168);
  --teal-accent-hover: oklch(55% 0.18 168);
  --teal-light: oklch(94% 0.06 168);
  --white: oklch(100% 0 0);
  --gray-50: oklch(98% 0.005 264);
  --gray-100: oklch(96% 0.005 264);
  --gray-200: oklch(92% 0.008 264);
  --gray-300: oklch(85% 0.01 264);
  --gray-400: oklch(70% 0.015 264);
  --gray-500: oklch(55% 0.015 264);
  --gray-600: oklch(40% 0.02 264);
  --gray-700: oklch(30% 0.02 264);
  --gray-800: oklch(22% 0.02 264);
  --text-primary: oklch(18% 0.02 264);
  --text-secondary: oklch(45% 0.02 264);
  --text-muted: oklch(60% 0.015 264);
  --shadow-sm: 0 1px 3px oklch(0% 0 0 / 0.08);
  --shadow-md: 0 4px 12px oklch(0% 0 0 / 0.1);
  --shadow-lg: 0 8px 30px oklch(0% 0 0 / 0.12);
  --shadow-xl: 0 16px 50px oklch(0% 0 0 / 0.15);
  --radius-sm: 8px;
  --radius-md: 12px;
  --radius-lg: 16px;
  --radius-xl: 24px;
  --radius-full: 9999px;
}

/* ===== RESET & BASE ===== */
*, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }

html {
  scroll-behavior: smooth;
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
}

body {
  font-family: 'Inter', -apple-system, BlinkMacSystemFont, 'Segoe UI', sans-serif;
  font-size: 16px;
  line-height: 1.6;
  color: var(--text-primary);
  background: var(--white);
  overflow-x: hidden;
}

a { text-decoration: none; color: inherit; }
ul { list-style: none; }
img { max-width: 100%; display: block; }
button { cursor: pointer; font-family: inherit; border: none; background: none; }
input, select { font-family: inherit; }

/* ===== UTILITIES ===== */
.container {
  max-width: 1200px;
  margin: 0 auto;
  padding: 0 24px;
}

.section-label {
  font-size: 14px;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 1.5px;
  color: var(--teal-accent);
  margin-bottom: 12px;
}

.section-title {
  font-size: clamp(28px, 4vw, 42px);
  font-weight: 800;
  line-height: 1.15;
  color: var(--text-primary);
  margin-bottom: 16px;
}

.section-subtitle {
  font-size: clamp(16px, 2vw, 18px);
  color: var(--text-secondary);
  max-width: 560px;
  line-height: 1.6;
}

/* ===== HEADER ===== */
.header {
  position: fixed;
  top: 0; left: 0; right: 0;
  z-index: 1000;
  background: oklch(100% 0 0 / 0.92);
  backdrop-filter: blur(12px);
  -webkit-backdrop-filter: blur(12px);
  border-bottom: 1px solid oklch(0% 0 0 / 0.06);
  transition: box-shadow 0.3s ease;
}

.header.scrolled {
  box-shadow: var(--shadow-md);
}

.header-inner {
  display: flex;
  align-items: center;
  justify-content: space-between;
  height: 72px;
}

.logo {
  display: flex;
  align-items: center;
  gap: 10px;
  font-size: 22px;
  font-weight: 800;
  color: var(--blue-primary);
}

.logo-icon {
  width: 36px;
  height: 36px;
  background: var(--blue-primary);
  border-radius: var(--radius-sm);
  display: flex;
  align-items: center;
  justify-content: center;
}

.logo-icon svg { width: 20px; height: 20px; }

.nav-desktop {
  display: flex;
  align-items: center;
  gap: 8px;
}

.nav-link {
  font-size: 15px;
  font-weight: 500;
  color: var(--text-secondary);
  padding: 8px 16px;
  border-radius: var(--radius-full);
  transition: all 0.2s ease;
}

.nav-link:hover {
  color: var(--blue-primary);
  background: var(--blue-light);
}

.nav-actions {
  display: flex;
  align-items: center;
  gap: 8px;
}

.btn-login {
  font-size: 15px;
  font-weight: 500;
  color: var(--blue-primary);
  padding: 8px 20px;
  border-radius: var(--radius-full);
  transition: all 0.2s ease;
}

.btn-login:hover {
  background: var(--blue-light);
}

.btn-signup {
  font-size: 15px;
  font-weight: 600;
  color: var(--white);
  background: var(--blue-primary);
  padding: 10px 24px;
  border-radius: var(--radius-full);
  transition: all 0.2s ease;
}

.btn-signup:hover {
  background: var(--blue-primary-hover);
  transform: translateY(-1px);
  box-shadow: 0 4px 12px oklch(52% 0.22 264 / 0.3);
}

.hamburger {
  display: none;
  flex-direction: column;
  gap: 5px;
  padding: 8px;
  z-index: 1001;
}

.hamburger span {
  display: block;
  width: 24px;
  height: 2.5px;
  background: var(--gray-700);
  border-radius: 2px;
  transition: all 0.3s ease;
}

.hamburger.active span:nth-child(1) {
  transform: rotate(45deg) translate(5px, 5px);
}
.hamburger.active span:nth-child(2) {
  opacity: 0;
}
.hamburger.active span:nth-child(3) {
  transform: rotate(-45deg) translate(6px, -6px);
}

/* Mobile drawer */
.mobile-drawer {
  position: fixed;
  top: 0; right: 0;
  width: 300px;
  max-width: 85vw;
  height: 100vh;
  background: var(--white);
  z-index: 999;
  transform: translateX(100%);
  transition: transform 0.35s cubic-bezier(0.4, 0, 0.2, 1);
  padding: 96px 32px 32px;
  box-shadow: var(--shadow-xl);
}

.mobile-drawer.open {
  transform: translateX(0);
}

.mobile-overlay {
  position: fixed;
  inset: 0;
  background: oklch(0% 0 0 / 0.4);
  z-index: 998;
  opacity: 0;
  pointer-events: none;
  transition: opacity 0.35s ease;
}

.mobile-overlay.active {
  opacity: 1;
  pointer-events: auto;
}

.mobile-drawer .nav-link {
  display: block;
  font-size: 18px;
  padding: 14px 0;
  border-bottom: 1px solid var(--gray-100);
  border-radius: 0;
}

.mobile-drawer .nav-actions {
  flex-direction: column;
  margin-top: 24px;
  gap: 12px;
}

.mobile-drawer .btn-login,
.mobile-drawer .btn-signup {
  width: 100%;
  text-align: center;
  padding: 14px;
  font-size: 16px;
}

/* ===== HERO ===== */
.hero {
  padding: 140px 0 80px;
  background: linear-gradient(165deg, var(--white) 0%, var(--blue-bg) 50%, oklch(94% 0.05 168) 100%);
  position: relative;
  overflow: hidden;
}

.hero::before {
  content: '';
  position: absolute;
  top: -200px;
  right: -200px;
  width: 600px;
  height: 600px;
  background: radial-gradient(circle, oklch(52% 0.22 264 / 0.06) 0%, transparent 70%);
  border-radius: 50%;
}

.hero::after {
  content: '';
  position: absolute;
  bottom: -100px;
  left: -100px;
  width: 400px;
  height: 400px;
  background: radial-gradient(circle, oklch(62% 0.16 168 / 0.06) 0%, transparent 70%);
  border-radius: 50%;
}

.hero-content {
  position: relative;
  z-index: 1;
  text-align: center;
  max-width: 720px;
  margin: 0 auto 48px;
}

.hero-badge {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  background: var(--teal-light);
  color: oklch(35% 0.12 168);
  font-size: 14px;
  font-weight: 600;
  padding: 6px 16px;
  border-radius: var(--radius-full);
  margin-bottom: 24px;
}

.hero-badge svg {
  width: 16px;
  height: 16px;
}

.hero-title {
  font-size: clamp(36px, 6vw, 56px);
  font-weight: 800;
  line-height: 1.1;
  color: var(--text-primary);
  margin-bottom: 20px;
}

.hero-title .highlight {
  background: linear-gradient(135deg, var(--blue-primary), var(--teal-accent));
  -webkit-background-clip: text;
  -webkit-text-fill-color: transparent;
  background-clip: text;
}

.hero-subtitle {
  font-size: clamp(17px, 2.2vw, 20px);
  color: var(--text-secondary);
  line-height: 1.6;
  max-width: 580px;
  margin: 0 auto;
}

/* ===== SEARCH BAR ===== */
.search-container {
  position: relative;
  z-index: 10;
  max-width: 880px;
  margin: 0 auto;
}

.search-bar {
  background: var(--white);
  border-radius: var(--radius-lg);
  box-shadow: var(--shadow-xl);
  padding: 8px;
  display: flex;
  align-items: stretch;
  gap: 4px;
  border: 2px solid transparent;
  transition: border-color 0.2s ease, box-shadow 0.2s ease;
}

.search-bar:focus-within {
  border-color: var(--blue-primary);
  box-shadow: var(--shadow-xl), 0 0 0 4px oklch(52% 0.22 264 / 0.1);
}

.search-field {
  flex: 1;
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 12px 16px;
  border-radius: var(--radius-md);
  position: relative;
  transition: background 0.2s ease;
}

.search-field:focus-within {
  background: var(--gray-50);
}

.search-field svg {
  width: 20px;
  height: 20px;
  color: var(--gray-400);
  flex-shrink: 0;
}

.search-field input,
.search-field select {
  border: none;
  outline: none;
  background: transparent;
  font-size: 15px;
  color: var(--text-primary);
  width: 100%;
}

.search-field input::placeholder {
  color: var(--gray-400);
}

.search-field select {
  appearance: none;
  -webkit-appearance: none;
  cursor: pointer;
}

.search-divider {
  width: 1px;
  background: var(--gray-200);
  align-self: stretch;
  margin: 8px 0;
}

.btn-search {
  background: var(--teal-accent);
  color: var(--white);
  font-size: 16px;
  font-weight: 600;
  padding: 14px 32px;
  border-radius: var(--radius-md);
  transition: all 0.2s ease;
  white-space: nowrap;
  display: flex;
  align-items: center;
  gap: 8px;
}

.btn-search:hover {
  background: var(--teal-accent-hover);
  transform: translateY(-1px);
  box-shadow: 0 4px 16px oklch(62% 0.16 168 / 0.35);
}

.btn-search svg {
  width: 18px;
  height: 18px;
}

/* Autocomplete dropdown */
.autocomplete-dropdown {
  position: absolute;
  top: calc(100% + 8px);
  left: 0;
  right: 0;
  background: var(--white);
  border-radius: var(--radius-md);
  box-shadow: var(--shadow-xl);
  border: 1px solid var(--gray-200);
  max-height: 320px;
  overflow-y: auto;
  display: none;
  z-index: 100;
}

.autocomplete-dropdown.active {
  display: block;
  animation: dropIn 0.2s ease;
}

@keyframes dropIn {
  from { opacity: 0; transform: translateY(-8px); }
  to { opacity: 1; transform: translateY(0); }
}

.autocomplete-item {
  display: flex;
  align-items: center;
  gap: 12px;
  padding: 12px 20px;
  cursor: pointer;
  transition: background 0.15s ease;
}

.autocomplete-item:hover,
.autocomplete-item.selected {
  background: var(--blue-light);
}

.autocomplete-item svg {
  width: 18px;
  height: 18px;
  color: var(--gray-400);
  flex-shrink: 0;
}

.autocomplete-item-text {
  font-size: 15px;
  color: var(--text-primary);
}

.autocomplete-item-category {
  font-size: 12px;
  color: var(--text-muted);
  margin-left: auto;
}

/* ===== STATS BAR ===== */
.stats-bar {
  padding: 48px 0;
  background: var(--white);
}

.stats-grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 32px;
  text-align: center;
}

.stat-item {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 8px;
}

.stat-icon {
  width: 48px;
  height: 48px;
  border-radius: var(--radius-md);
  display: flex;
  align-items: center;
  justify-content: center;
  margin-bottom: 4px;
}

.stat-icon.blue { background: var(--blue-light); color: var(--blue-primary); }
.stat-icon.teal { background: var(--teal-light); color: var(--teal-accent); }

.stat-icon svg { width: 24px; height: 24px; }

.stat-number {
  font-size: clamp(28px, 4vw, 36px);
  font-weight: 800;
  color: var(--text-primary);
  line-height: 1;
}

.stat-label {
  font-size: 14px;
  color: var(--text-secondary);
  font-weight: 500;
  max-width: 180px;
}

/* ===== SPECIALTIES ===== */
.specialties {
  padding: 80px 0;
  background: var(--gray-50);
}

.specialties-header {
  text-align: center;
  margin-bottom: 48px;
}

.specialties-header .section-subtitle {
  margin: 0 auto;
}

.specialties-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 20px;
}

.specialty-card {
  background: var(--white);
  border-radius: var(--radius-lg);
  padding: 28px 24px;
  display: flex;
  align-items: flex-start;
  gap: 16px;
  box-shadow: var(--shadow-sm);
  border: 1px solid var(--gray-100);
  transition: all 0.25s ease;
  cursor: pointer;
}

.specialty-card:hover {
  transform: translateY(-4px);
  box-shadow: var(--shadow-lg);
  border-color: var(--blue-primary);
}

.specialty-card:hover .specialty-icon {
  background: var(--blue-primary);
  color: var(--white);
}

.specialty-icon {
  width: 52px;
  height: 52px;
  border-radius: var(--radius-md);
  background: var(--blue-light);
  color: var(--blue-primary);
  display: flex;
  align-items: center;
  justify-content: center;
  flex-shrink: 0;
  transition: all 0.25s ease;
}

.specialty-icon svg { width: 24px; height: 24px; }

.specialty-info { flex: 1; }

.specialty-name {
  font-size: 17px;
  font-weight: 700;
  color: var(--text-primary);
  margin-bottom: 4px;
}

.specialty-desc {
  font-size: 14px;
  color: var(--text-secondary);
  line-height: 1.5;
}

.specialty-arrow {
  color: var(--gray-300);
  transition: all 0.25s ease;
  align-self: center;
  flex-shrink: 0;
}

.specialty-card:hover .specialty-arrow {
  color: var(--blue-primary);
  transform: translateX(4px);
}

.specialty-arrow svg { width: 20px; height: 20px; }

/* ===== HOW IT WORKS ===== */
.how-it-works {
  padding: 80px 0;
  background: var(--white);
}

.how-it-works-header {
  text-align: center;
  margin-bottom: 56px;
}

.how-it-works-header .section-subtitle {
  margin: 0 auto;
}

.steps-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 40px;
  position: relative;
}

.steps-grid::before {
  content: '';
  position: absolute;
  top: 48px;
  left: calc(16.67% + 24px);
  right: calc(16.67% + 24px);
  height: 2px;
  background: linear-gradient(90deg, var(--blue-primary), var(--teal-accent));
  border-radius: 1px;
}

.step-card {
  text-align: center;
  position: relative;
}

.step-number {
  width: 96px;
  height: 96px;
  border-radius: 50%;
  display: flex;
  align-items: center;
  justify-content: center;
  margin: 0 auto 24px;
  font-size: 32px;
  font-weight: 800;
  position: relative;
  z-index: 1;
}

.step-card:nth-child(1) .step-number {
  background: var(--blue-light);
  color: var(--blue-primary);
}

.step-card:nth-child(2) .step-number {
  background: oklch(95% 0.04 200);
  color: oklch(50% 0.2 200);
}

.step-card:nth-child(3) .step-number {
  background: var(--teal-light);
  color: var(--teal-accent);
}

.step-title {
  font-size: 20px;
  font-weight: 700;
  color: var(--text-primary);
  margin-bottom: 10px;
}

.step-desc {
  font-size: 15px;
  color: var(--text-secondary);
  line-height: 1.6;
  max-width: 300px;
  margin: 0 auto;
}

/* ===== TESTIMONIALS ===== */
.testimonials {
  padding: 80px 0;
  background: var(--gray-50);
}

.testimonials-header {
  text-align: center;
  margin-bottom: 48px;
}

.testimonials-header .section-subtitle {
  margin: 0 auto;
}

.testimonials-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 24px;
}

.testimonial-card {
  background: var(--white);
  border-radius: var(--radius-lg);
  padding: 32px;
  box-shadow: var(--shadow-sm);
  border: 1px solid var(--gray-100);
  display: flex;
  flex-direction: column;
  gap: 20px;
  transition: all 0.25s ease;
}

.testimonial-card:hover {
  box-shadow: var(--shadow-md);
}

.testimonial-stars {
  display: flex;
  gap: 2px;
  color: oklch(78% 0.16 85);
}

.testimonial-stars svg { width: 18px; height: 18px; }

.testimonial-text {
  font-size: 16px;
  color: var(--text-secondary);
  line-height: 1.7;
  flex: 1;
  font-style: italic;
}

.testimonial-author {
  display: flex;
  align-items: center;
  gap: 12px;
}

.testimonial-avatar {
  width: 44px;
  height: 44px;
  border-radius: 50%;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 16px;
  font-weight: 700;
  color: var(--white);
}

.testimonial-card:nth-child(1) .testimonial-avatar { background: oklch(60% 0.18 280); }
.testimonial-card:nth-child(2) .testimonial-avatar { background: oklch(60% 0.18 200); }
.testimonial-card:nth-child(3) .testimonial-avatar { background: var(--teal-accent); }

.testimonial-name {
  font-size: 15px;
  font-weight: 600;
  color: var(--text-primary);
}

.testimonial-location {
  font-size: 13px;
  color: var(--text-muted);
}

/* ===== MOBILE APP PROMO ===== */
.app-promo {
  padding: 80px 0;
  background: var(--white);
}

.app-promo-inner {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 64px;
  align-items: center;
}

.app-promo-content {
  max-width: 480px;
}

.app-promo .section-title {
  margin-bottom: 16px;
}

.app-promo .section-subtitle {
  margin-bottom: 32px;
  max-width: 440px;
}

.app-features {
  display: flex;
  flex-direction: column;
  gap: 16px;
  margin-bottom: 36px;
}

.app-feature {
  display: flex;
  align-items: center;
  gap: 12px;
  font-size: 15px;
  color: var(--text-secondary);
}

.app-feature-icon {
  width: 32px;
  height: 32px;
  border-radius: 50%;
  background: var(--teal-light);
  color: var(--teal-accent);
  display: flex;
  align-items: center;
  justify-content: center;
  flex-shrink: 0;
}

.app-feature-icon svg { width: 16px; height: 16px; }

.app-buttons {
  display: flex;
  gap: 12px;
  flex-wrap: wrap;
}

.app-store-btn {
  display: inline-flex;
  align-items: center;
  gap: 10px;
  background: var(--text-primary);
  color: var(--white);
  padding: 12px 24px;
  border-radius: var(--radius-md);
  transition: all 0.2s ease;
}

.app-store-btn:hover {
  transform: translateY(-2px);
  box-shadow: var(--shadow-lg);
}

.app-store-btn svg { width: 24px; height: 24px; }

.app-store-btn-text {
  display: flex;
  flex-direction: column;
  line-height: 1.2;
}

.app-store-btn-text small {
  font-size: 10px;
  font-weight: 500;
  opacity: 0.8;
}

.app-store-btn-text strong {
  font-size: 15px;
  font-weight: 600;
}

/* Phone mockup */
.app-promo-visual {
  display: flex;
  justify-content: center;
  align-items: center;
  position: relative;
}

.phone-mockup {
  width: 280px;
  height: 560px;
  background: var(--gray-800);
  border-radius: 40px;
  padding: 12px;
  position: relative;
  box-shadow: var(--shadow-xl);
}

.phone-mockup::before {
  content: '';
  position: absolute;
  top: 16px;
  left: 50%;
  transform: translateX(-50%);
  width: 80px;
  height: 24px;
  background: var(--gray-700);
  border-radius: 12px;
  z-index: 2;
}

.phone-screen {
  width: 100%;
  height: 100%;
  background: linear-gradient(165deg, var(--blue-primary), oklch(55% 0.18 200), var(--teal-accent));
  border-radius: 30px;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 16px;
  padding: 60px 24px 40px;
  color: var(--white);
  overflow: hidden;
}

.phone-screen-icon {
  width: 64px;
  height: 64px;
  border-radius: var(--radius-lg);
  background: oklch(100% 0 0 / 0.2);
  display: flex;
  align-items: center;
  justify-content: center;
}

.phone-screen-icon svg { width: 32px; height: 32px; }

.phone-screen-title {
  font-size: 22px;
  font-weight: 700;
  text-align: center;
}

.phone-screen-subtitle {
  font-size: 14px;
  opacity: 0.85;
  text-align: center;
  line-height: 1.5;
}

.phone-mockup-cards {
  width: 100%;
  display: flex;
  flex-direction: column;
  gap: 8px;
  margin-top: 8px;
}

.phone-mockup-card {
  background: oklch(100% 0 0 / 0.15);
  border-radius: var(--radius-sm);
  padding: 10px 14px;
  font-size: 13px;
  font-weight: 500;
}

/* Floating decorations */
.app-promo-visual .float-dot {
  position: absolute;
  border-radius: 50%;
  animation: float 6s ease-in-out infinite;
}

.app-promo-visual .float-dot:nth-child(1) {
  width: 12px; height: 12px;
  background: var(--teal-accent);
  top: 15%; left: 10%;
  animation-delay: 0s;
}

.app-promo-visual .float-dot:nth-child(2) {
  width: 8px; height: 8px;
  background: var(--blue-primary);
  top: 60%; right: 5%;
  animation-delay: 2s;
}

.app-promo-visual .float-dot:nth-child(3) {
  width: 10px; height: 10px;
  background: oklch(78% 0.16 85);
  bottom: 20%; left: 5%;
  animation-delay: 4s;
}

@keyframes float {
  0%, 100% { transform: translateY(0); }
  50% { transform: translateY(-12px); }
}

/* ===== FOOTER ===== */
.footer {
  padding: 64px 0 32px;
  background: oklch(14% 0.02 264);
  color: oklch(80% 0.01 264);
}

.footer-grid {
  display: grid;
  grid-template-columns: 2fr 1fr 1fr 1fr 1fr;
  gap: 40px;
  margin-bottom: 48px;
}

.footer-brand {
  max-width: 280px;
}

.footer-logo {
  display: flex;
  align-items: center;
  gap: 10px;
  font-size: 20px;
  font-weight: 800;
  color: var(--white);
  margin-bottom: 16px;
}

.footer-logo-icon {
  width: 32px;
  height: 32px;
  background: var(--blue-primary);
  border-radius: 6px;
  display: flex;
  align-items: center;
  justify-content: center;
}

.footer-logo-icon svg { width: 18px; height: 18px; }

.footer-brand p {
  font-size: 14px;
  line-height: 1.6;
  color: oklch(65% 0.01 264);
}

.footer-heading {
  font-size: 14px;
  font-weight: 600;
  color: var(--white);
  text-transform: uppercase;
  letter-spacing: 1px;
  margin-bottom: 16px;
}

.footer-links {
  display: flex;
  flex-direction: column;
  gap: 10px;
}

.footer-link {
  font-size: 14px;
  color: oklch(65% 0.01 264);
  transition: color 0.2s ease;
}

.footer-link:hover {
  color: var(--white);
}

.footer-bottom {
  border-top: 1px solid oklch(25% 0.02 264);
  padding-top: 24px;
  display: flex;
  justify-content: space-between;
  align-items: center;
  font-size: 13px;
  color: oklch(55% 0.01 264);
}

.footer-bottom-links {
  display: flex;
  gap: 24px;
}

.footer-bottom-links a {
  color: oklch(55% 0.01 264);
  transition: color 0.2s ease;
}

.footer-bottom-links a:hover {
  color: oklch(80% 0.01 264);
}

/* ===== RESPONSIVE ===== */
@media (max-width: 1024px) {
  .specialties-grid {
    grid-template-columns: repeat(2, 1fr);
  }

  .app-promo-inner {
    grid-template-columns: 1fr;
    gap: 48px;
  }

  .app-promo-content {
    max-width: 100%;
    text-align: center;
  }

  .app-promo .section-subtitle {
    margin-left: auto;
    margin-right: auto;
  }

  .app-features {
    align-items: center;
  }

  .app-buttons {
    justify-content: center;
  }

  .footer-grid {
    grid-template-columns: 1fr 1fr 1fr;
  }

  .footer-brand {
    grid-column: 1 / -1;
  }
}

@media (max-width: 768px) {
  .nav-desktop, .nav-actions { display: none; }
  .hamburger { display: flex; }

  .hero {
    padding: 120px 0 60px;
  }

  .hero-title {
    font-size: clamp(30px, 7vw, 42px);
  }

  .search-bar {
    flex-direction: column;
    padding: 12px;
    gap: 8px;
  }

  .search-divider {
    width: 100%;
    height: 1px;
    margin: 0;
  }

  .btn-search {
    width: 100%;
    justify-content: center;
    padding: 16px;
  }

  .stats-grid {
    grid-template-columns: repeat(2, 1fr);
    gap: 24px;
  }

  .specialties-grid {
    grid-template-columns: 1fr;
  }

  .steps-grid {
    grid-template-columns: 1fr;
    gap: 32px;
  }

  .steps-grid::before { display: none; }

  .testimonials-grid {
    grid-template-columns: 1fr;
  }

  .footer-grid {
    grid-template-columns: 1fr 1fr;
    gap: 32px;
  }

  .footer-brand {
    grid-column: 1 / -1;
  }

  .footer-bottom {
    flex-direction: column;
    gap: 16px;
    text-align: center;
  }

  .footer-bottom-links {
    flex-wrap: wrap;
    justify-content: center;
    gap: 16px;
  }
}

@media (max-width: 480px) {
  .container {
    padding: 0 16px;
  }

